import os,re
root='AlgebraicJacobian.lean'
def imports(p):
    try: t=open(p).read()
    except: return []
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)', t, re.M)
def path(m): return m.replace('.','/')+'.lean'
seen=set(); stack=imports(root)
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    stack+=imports(path(m))
allf=set()
for d,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            allf.add(os.path.join(d,f)[:-5].replace('/','.'))
unreach=sorted(allf-seen)
print('total modules:',len(allf),'reachable:',len(seen & allf),'UNREACHABLE:',len(unreach))
for u in unreach: print('   ',u)
EOF

